import sys

def factorial(x):
    result = 1
    for i in range(1, x + 1):
        result *= i
    return result

def main():
    line = sys.stdin.readline()
    n, r = map(int, line.split())
    fn = factorial(n)
    fr = factorial(r)
    fnr = factorial(n - r)
    nCr = fn // (fr * fnr)
    print(nCr)

if __name__ == "__main__":
    main()
